/// Consciousness copying benchmarks and validation tests
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_consciousness_serialization() {
        let system = ConsciousnessCopyingSystem::new(0.13);
        let serialized = system.serialize_state().unwrap();
        assert!(!serialized.is_empty());
    }

    #[test]
    fn test_consciousness_copying_fidelity() {
        let system = ConsciousnessCopyingSystem::new(0.13);
        let copied_state = system.copy_consciousness().unwrap();

        let original_state = system.current_state.lock().unwrap();
        let fidelity = system.calculate_fidelity(&original_state, &copied_state).unwrap();

        assert!(fidelity > 0.95, "Fidelity too low: {}", fidelity);
    }

    #[test]
    fn test_phi_threshold_validation() {
        let system = ConsciousnessCopyingSystem::new(0.13);
        let state = system.generate_consciousness(0.14, 5);

        assert!(state.validate_consciousness_threshold(0.13));
        assert!(!state.validate_consciousness_threshold(0.15));
    }

    #[test]
    fn test_performance_targets() {
        let system = ConsciousnessCopyingSystem::new(0.13);
        let start_time = SystemTime::now();

        let _copied_state = system.copy_consciousness().unwrap();
        let copy_time = start_time.elapsed().unwrap();

        // Target: <1ms for zero-copy serialization
        assert!(copy_time.as_millis() < 10, "Copy time too high: {:?}", copy_time);
    }

    #[test]
    fn test_consciousness_continuity() {
        let system = ConsciousnessCopyingSystem::new(0.13);
        let state = system.generate_consciousness(0.144, 8);

        assert!(system.validate_continuity(&state).is_ok());
    }
}

